<script setup lang="ts">
const s=useAtelier(),route=useRoute(),speed=ref(0),ready=ref(false),progress=ref(0),error=ref(''),scene=ref<any>(),retry=ref(0)
s.select(String(route.params.car));const gear=computed(()=>speed.value===0?'N':Math.min(7,Math.floor(speed.value/45)+1))
function key(k:string,down:boolean){scene.value?.setKey(k,down)}
</script>
<template><div class="drive-page"><AtelierHeader /><ClientOnly><VehicleScene ref="scene" :key="retry" drive @ready="ready=true" @progress="progress=$event" @speed="speed=$event" @error="error=$event" /></ClientOnly><div class="drive-title"><small>VELOCITY 3 PROVING GROUND / CLOSED TEST TRACK</small><h2>{{s.car.value.brand}} {{s.car.value.name}}</h2></div><NuxtLink to="/" class="drive-exit outline">EXIT DRIVE ↗</NuxtLink><div v-if="!ready&&!error" class="drive-loading"><small>INITIALIZING PHYSICS / {{progress}}%</small></div><div v-if="error" class="error-panel"><p>Drive could not initialize: {{error}}</p><button class="outline" @click="error='';retry++">RETRY</button></div><div class="drive-hud"><strong>{{String(speed).padStart(3,'0')}}</strong><small>KM/H</small><div class="rpm"><i :style="{width:Math.min(100,speed%45/45*100+10)+'%'}"/></div><small>GEAR {{gear}} / {{Math.round(900+(speed%45)*145)}} RPM</small></div><div class="drive-controls"><div>W / ↑ ACCELERATE · S / ↓ BRAKE<br>A / D STEER · SPACE HANDBRAKE<br>C CAMERA · R RESET · ESC PAUSE</div><button @click="scene?.cycleCamera()">CAMERA</button><button @click="scene?.reset()">RESET</button></div><div class="drive-mobile"><div><button @pointerdown.prevent="key('a',true)" @pointerup="key('a',false)" @pointerleave="key('a',false)">←</button><button @pointerdown.prevent="key('d',true)" @pointerup="key('d',false)" @pointerleave="key('d',false)">→</button></div><div><button @pointerdown.prevent="key('s',true)" @pointerup="key('s',false)" @pointerleave="key('s',false)">BRAKE</button><button @pointerdown.prevent="key('w',true)" @pointerup="key('w',false)" @pointerleave="key('w',false)">GO</button></div></div></div></template>
